{
  "name": "Luminos电动俯仰轴",
  "name_en": "Luminos Motorized Pitch Axis",
  "manufacturer": "Zaber Technologies",
  "description": "这是一种用于精密定位平台的电动俯仰旋转轴，常见于多轴光学对准或光子器件耦合系统中。它可对样品、光纤、透镜或其他光学元件进行细微倾角调节，并支持回零、绝对/相对移动及微步控制，适合实验室中的高精度角度对准任务。",
  "description_en": "This is a motorized pitch rotation axis for precision positioning stages, commonly used in multi-axis optical alignment or photonics coupling systems. It provides fine tilt adjustment of samples, fibers, lenses, or other optical components, and supports homing, absolute/relative motion, and microstepping for high-precision angular alignment in the lab.",
  "tag_hints": [
    "optical alignment",
    "motorized pitch adjustment",
    "precision angular positioning",
    "fiber alignment",
    "microstepping",
    "multi-axis stage"
  ],
  "actions": [
    {
      "action_name": "auto-arc_second_per_step",
      "description": "获取每步对应的弧秒角位移。",
      "description_en": "Get the angular step size in arcseconds per step."
    },
    {
      "action_name": "auto-home",
      "description": "使俯仰轴回零并寻找参考位置。",
      "description_en": "Home the pitch axis to its reference position."
    },
    {
      "action_name": "auto-set_default_settings",
      "description": "恢复设备默认设置。",
      "description_en": "Restore the device's default settings."
    },
    {
      "action_name": "auto-set_manual_mode",
      "description": "设为手动控制模式。",
      "description_en": "Set the device to manual control mode."
    },
    {
      "action_name": "auto-set_computer_mode",
      "description": "设为计算机控制模式。",
      "description_en": "Set the device to computer control mode."
    },
    {
      "action_name": "auto-flash_leds",
      "description": "闪烁设备指示灯以便识别。",
      "description_en": "Flash the device LEDs for identification."
    },
    {
      "action_name": "auto-move_rel",
      "description": "按给定相对量转动俯仰轴。",
      "description_en": "Move the pitch axis by a relative amount."
    },
    {
      "action_name": "auto-move_abs",
      "description": "移动俯仰轴到指定绝对位置。",
      "description_en": "Move the pitch axis to a specified absolute position."
    },
    {
      "action_name": "auto-get_device_mode_bit_status",
      "description": "获取设备模式位状态。",
      "description_en": "Get the device mode bit status."
    },
    {
      "action_name": "auto-turn_leds_off",
      "description": "关闭设备指示灯。",
      "description_en": "Turn the device LEDs off."
    },
    {
      "action_name": "auto-turn_leds_on",
      "description": "打开设备指示灯。",
      "description_en": "Turn the device LEDs on."
    },
    {
      "action_name": "auto-enable_motor_knob",
      "description": "启用电机调节旋钮。",
      "description_en": "Enable the motor control knob."
    },
    {
      "action_name": "auto-disable_motor_knob",
      "description": "禁用电机调节旋钮。",
      "description_en": "Disable the motor control knob."
    },
    {
      "action_name": "auto-enable_manual_move_reply",
      "description": "启用手动移动回报。",
      "description_en": "Enable manual-move reporting."
    },
    {
      "action_name": "auto-disable_manual_move_reply",
      "description": "禁用手动移动回报。",
      "description_en": "Disable manual-move reporting."
    },
    {
      "action_name": "auto-enable_circular_phase_microstepping",
      "description": "启用圆相位微步。",
      "description_en": "Enable circular-phase microstepping."
    },
    {
      "action_name": "auto-disable_circular_phase_microstepping",
      "description": "禁用圆相位微步。",
      "description_en": "Disable circular-phase microstepping."
    },
    {
      "action_name": "auto-enable_anti_backlash_routine",
      "description": "启用消隙程序。",
      "description_en": "Enable the anti-backlash routine."
    },
    {
      "action_name": "auto-disable_anti_backlash_routine",
      "description": "禁用消隙程序。",
      "description_en": "Disable the anti-backlash routine."
    },
    {
      "action_name": "auto-enable_anti_sticktion_routine",
      "description": "启用防静摩擦程序。",
      "description_en": "Enable the anti-stiction routine."
    },
    {
      "action_name": "auto-disable_anti_sticktion_routine",
      "description": "禁用防静摩擦程序。",
      "description_en": "Disable the anti-stiction routine."
    },
    {
      "action_name": "auto-enable_move_tracking",
      "description": "启用运动跟踪。",
      "description_en": "Enable move tracking."
    },
    {
      "action_name": "auto-disable_move_tracking",
      "description": "禁用运动跟踪。",
      "description_en": "Disable move tracking."
    },
    {
      "action_name": "auto-get_speed",
      "description": "获取移动速度设置。",
      "description_en": "Get the motion speed setting."
    },
    {
      "action_name": "auto-set_speed",
      "description": "设置移动速度。",
      "description_en": "Set the motion speed."
    },
    {
      "action_name": "auto-get_acceleration",
      "description": "获取加速度设置。",
      "description_en": "Get the acceleration setting."
    },
    {
      "action_name": "auto-set_acceleration",
      "description": "设置加速度。",
      "description_en": "Set the acceleration."
    },
    {
      "action_name": "auto-get_microstep_resolution",
      "description": "获取微步分辨率设置。",
      "description_en": "Get the microstep resolution setting."
    },
    {
      "action_name": "auto-set_microstep_resolution",
      "description": "设置微步分辨率。",
      "description_en": "Set the microstep resolution."
    },
    {
      "action_name": "auto-nm_per_step",
      "description": "获取每步对应的纳米标定值。",
      "description_en": "Get the calibrated nanometers-per-step value."
    }
  ]
}

